// ==== OPERATOR INPUTS (edit before each run) ====
// Paste a FRESH ZeroGPU quota snapshot from https://huggingface.co/api/spaces/zero-gpu/quota
const QUOTA = {"base":2400,"current":0,"overquotaUsed":0,"observed_at":"1970-01-01T00:00:00.000Z"};
// =================================================

const spec = {
  reel_id: 'presenter_reel_1729964288705272356_v1',
  product_id: '1729964288705272356',
  pack_quantity: '1 Packung',
  presenter_image_url: 'https://files.catbox.moe/zaisoi.png',
  quota: QUOTA,
  caption_de: 'Gesichtsreinigung mit integriertem Bürstenkopf — dieses Angebot von MomoTek1 wird als Reiniger mit Kurkuma beworben. Anwendung laut Händler: anfeuchten, Schaum verteilen, gründlich abspülen. Erhältlich als 1er-, 2er- oder 3er-Pack. Details im verlinkten Shop. #gesichtsreinigung #skincarede #tiktokshopde #bizpunk72',
  scenes: [
    {id:'hook', kind:'presenter',
     text:'Du suchst Gesichtsreinigung mit Bürstenkopf?',
     prompt:'The same woman from the reference image speaks naturally to the camera in the same bright room. Preserve her identity, hairstyle, clothing and facial features. Restrained, realistic articulation with modest jaw openings and relaxed lips. Subtle head movements and natural blinking. After the spoken sentence ends, she rests with her mouth gently closed. Static camera, no cuts, no new objects.'},
    {id:'product', kind:'images',
     text:'Dieses Angebot von MomoTek1 zeigt eine Reinigerflasche mit integriertem Bürstenkopf. Beworben wird sie als Gesichtsreiniger mit Kurkuma.',
     images:['https://files.catbox.moe/dx6685.png','https://files.catbox.moe/n85f6w.png']},
    {id:'usage', kind:'images',
     text:'Die Anwendung laut Händler: Gesicht anfeuchten, Reinigungsschaum sanft verteilen und anschließend gründlich abspülen.',
     images:['https://files.catbox.moe/kbl8cd.png','https://files.catbox.moe/n85f6w.png']},
    {id:'selection', kind:'images',
     text:'Du kannst zwischen einer, zwei oder drei Packungen wählen. Schau vor dem Kauf auf die vollständige Inhaltsstoffliste und die genaue Variante.',
     images:['https://files.catbox.moe/i5rmyl.png','https://files.catbox.moe/dx6685.png']},
    {id:'cta', kind:'presenter',
     text:'Die Produktdetails findest du im verlinkten TikTok Shop.',
     prompt:'The same woman from the reference image speaks naturally to the camera in the same bright room. Preserve her identity, hairstyle, clothing and facial features. Restrained, realistic articulation with modest jaw openings and relaxed lips. Subtle head movements and natural blinking. After the spoken sentence ends, she rests with her mouth gently closed. Static camera, no cuts, no new objects.'}
  ]
};
// Rerun overrides (partial-failure recovery): presenter scene -> video_url, images scene -> audio_url
return [{json: spec}];

const spec = $input.first()?.json || {};
const q = spec.quota || {};
const ageMs = Date.now() - Date.parse(String(q.observed_at || ''));
if (!Number.isFinite(ageMs) || ageMs < 0 || ageMs > 120000) {
  throw new Error('Quota evidence missing or older than 120s - paste a fresh snapshot into Build Reel Spec');
}
if (!(Number(q.current) >= 1200)) {
  throw new Error('ZeroGPU quota too low for two LongCat submits (need >=1200s, got ' + q.current + ')');
}
if (Number(q.overquotaUsed) !== 0) {
  throw new Error('Overquota already used - included-quota-only policy blocks submission');
}
return [{json: spec}];

const spec = $('Build Reel Spec').first().json;
const HF_AUTH = { Authorization: 'Bearer ' + ($env.HF_TOKEN || '') };
const sp = 'resembleai-chatterbox-multilingual-tts.hf.space';
const T = (p, ms) => Promise.race([p, new Promise(r => setTimeout(() => r(null), ms))]);

let refFileObj = null;
try {
  const upResp = $('Upload Luisa Ref To HF').first().json;
  const upArr = typeof upResp === 'string' ? JSON.parse(upResp) : upResp;
  const upPath = Array.isArray(upArr) ? upArr[0] : (upArr && upArr.files && upArr.files[0]);
  if (upPath && String(upPath).startsWith('/')) {
    refFileObj = { path: String(upPath), url: 'https://' + sp + '/gradio_api/file=' + String(upPath),
      orig_name: 'luisa_ref.mp3', mime_type: 'audio/mpeg', size: null, is_stream: false,
      meta: { _type: 'gradio.FileData' } };
  }
} catch (e) {}
if (!refFileObj) throw new Error('Luisa reference upload path missing');

const chatterboxWav = async (text) => {
  const callResp = await T(this.helpers.httpRequest({
    method: 'POST', url: 'https://' + sp + '/gradio_api/call/generate_tts_audio',
    headers: { 'Content-Type': 'application/json', ...HF_AUTH },
    body: JSON.stringify({ data: [text, 'de', refFileObj, 0.72, 0.8, 42, 0.05] }),
    timeout: 8000 }), 15000);
  const callObj = typeof callResp === 'string' ? JSON.parse(callResp) : callResp;
  if (!callObj || !callObj.event_id) return null;
  const sseText = await T(this.helpers.httpRequest({
    method: 'GET', url: 'https://' + sp + '/gradio_api/call/generate_tts_audio/' + callObj.event_id,
    headers: HF_AUTH, timeout: 60000 }), 90000);
  if (!sseText) return null;
  for (const line of String(sseText).split('\n')) {
    if (line.startsWith('data: ') && line.trim() !== 'data: null') {
      const d = JSON.parse(line.slice(6));
      if (Array.isArray(d) && d[0] && d[0].url) {
        const wavBuf = Buffer.from(await T(this.helpers.httpRequest({
          method: 'GET', url: d[0].url, headers: HF_AUTH, encoding: 'arraybuffer', timeout: 15000 }), 20000));
        if (wavBuf && wavBuf.length > 44 && wavBuf.length < 2000000) return wavBuf;
      }
    }
  }
  return null;
};

const items = [];
for (const scene of spec.scenes) {
  if (scene.video_url || scene.audio_url) {
    items.push({ json: { scene, kind: 'ready' } });
    continue;
  }
  const wav = await chatterboxWav(scene.text);
  if (!wav) throw new Error('Chatterbox TTS failed for scene ' + scene.id + ' - aborting, no silent audio');
  const bin = await this.helpers.prepareBinaryData(wav, scene.id + '.wav', 'audio/wav');
  items.push({ json: { scene, kind: scene.kind }, binary: { voice: bin } });
}
return items;

const scene = $('Generate TTS Segments').item.json.scene;
const mia = $('Fetch Mia Crop').first().binary.data;
const voice16 = $input.item.binary.voice16;
const normUrl = $('Normalize Narration').item.json.file_url;
return [{ json: { scene, narration_16k_url: normUrl },
         binary: { voice16, image: mia } }];

const scene = $('Attach Scene And Mia').item.json.scene;
const body = String($input.item.json || $input.item.body || '');
let url = '';
let ev = '';
for (const raw of body.split('\n')) {
  const line = raw.trimEnd();
  if (line.startsWith('event:')) ev = line.slice(6).trim();
  else if (line.startsWith('data:') && ev === 'complete') {
    const d = JSON.parse(line.slice(5).trim());
    const v = (d[0] && (d[0].video || d[0])) || {};
    url = v.url || ('https://bizpunk-tiktok-longcat-worker.hf.space/gradio_api/file=' + (v.path || ''));
  } else if (line.startsWith('data:') && ev === 'error') {
    throw new Error('LongCat provider rejected the job for scene ' + scene.id + ' - no automatic retry');
  }
}
if (!url.startsWith('https://bizpunk-tiktok-longcat-worker.hf.space/gradio_api/file=/tmp/gradio/') || !url.endsWith('.mp4')) {
  throw new Error('LongCat result missing/invalid for scene ' + scene.id + ' - do not resubmit without checking job state');
}
return [{ json: { scene, hf_clip_url: url } }];

const spec = $('Build Reel Spec').first().json;
const imgMap = {};
for (const it of $('Attach Asset Key').all()) imgMap[it.json.key] = it.json.file_url;
const clips = {};
for (const it of $('Attach Clip URL').all()) clips[it.json.scene_id] = it.json.video_url;
const auds = {};
for (const it of $('Attach Audio URL').all()) auds[it.json.scene_id] = it.json.audio_url;
const scenes = [];
for (const s of spec.scenes) {
  if (s.kind === 'presenter') {
    const v = s.video_url || clips[s.id];
    if (!v) throw new Error('Missing presenter clip for scene ' + s.id);
    scenes.push({ type: 'video', url: v, text: s.text, cropTo916: true });
  } else {
    const a = s.audio_url || auds[s.id];
    if (!a) throw new Error('Missing narration audio for scene ' + s.id);
    const urls = (s.images || []).map(u => imgMap[u] || u);
    scenes.push({ type: 'images', urls, audioUrl: a, text: s.text });
  }
}
return [{ json: { scenes, reel_id: spec.reel_id, caption_de: spec.caption_de, product_id: spec.product_id, pack_quantity: spec.pack_quantity } }];

const presign = $input.first()?.json || {};
const reel = $('Fetch Rendered Reel').first() || {};
return [{ json: presign, binary: reel.binary || {} }];

const spec = $('Assemble Render Spec').first()?.json || {};
const presign = $('Zernio Presign Video').first()?.json || {};
const reelUrl = String(presign.publicUrl || presign.url || '');
const zernioBody = {
  content: String(spec.caption_de || ''),
  publishNow: true,
  platforms: [{ platform: 'tiktok', accountId: '6a99599b77555aae01ce4ec4' }],
  mediaItems: reelUrl ? [{ type: 'video', url: reelUrl }] : [],
  tiktokSettings: {
    draft: true,
    is_ai_generated: true,
    privacy_level: 'PUBLIC_TO_EVERYONE',
    allow_comment: true,
    allow_duet: true,
    allow_stitch: true,
    content_preview_confirmed: true,
    express_consent_given: true
  }
};
return [{ json: { ...spec, final_video_url: reelUrl, zernio_body: JSON.stringify(zernioBody) } }];

const prev = $('Prepare Zernio Draft Payload').first()?.json || {};
const zResp = $input.first()?.json || {};
const postObj = zResp.post || zResp.data?.post || zResp.data || {};
if (zResp.error || !postObj._id) throw new Error('Zernio draft creation failed or returned no post ID');
const platform = (Array.isArray(postObj.platforms) ? postObj.platforms : []).find(p => p.platform === 'tiktok' && p.status === 'published' && String(p.platformPostId || '').startsWith('v_inbox_url') && p.platformSpecificData?.isDraft === true && p.platformSpecificData?.tiktokSettings?.draft === true && p.platformSpecificData?.tiktokSettings?.is_ai_generated === true);
if (!platform) throw new Error('Zernio response does not confirm an AI-disclosed TikTok Creator Inbox draft');
return [{ json: { ...prev, zernio_post_id: String(postObj._id), publish_status: 'draft_in_inbox' } }];

const spec = $('Build Reel Spec').first().json;
const seen = new Set();
const items = [];
for (const s of spec.scenes) {
  for (const u of (s.images || [])) {
    if (!seen.has(u)) { seen.add(u); items.push({ json: { key: u } }); }
  }
}
return items;

const key = $('Collect Image Assets').item.json.key;
const file_url = $('Store Asset').item.json.file_url;
return [{ json: { key, file_url } }];
